def pancake_sort(arr):
    def flip(sub_arr, k):
        i, j = 0, k
        while i < j:
            sub_arr[i], sub_arr[j] = sub_arr[j], sub_arr[i]
            i += 1
            j -= 1

    n = len(arr)
    for size in range(n, 1, -1):
        max_idx = max(range(size), key=arr.__getitem__)
        if max_idx != size - 1:
            if max_idx != 0:
                flip(arr, max_idx)
            flip(arr, size - 1)
    return arr

