    def is_palindrome(x):
        return x == x[::-1]

    if is_palindrome(s):
        n += 1
        s = str(n)

    half = (length + 1) // 2
    left = s[:half]
    if length % 2 == 0:
        pal_candidate = left + left[::-1]
    else:
        pal_candidate = left + left[-2::-1]

    if int(pal_candidate) > n:
        return int(pal_candidate)

    # Increment the left half and form palindrome again
    left_num = int(left) + 1
    left = str(left_num)
    if len(left) > half:  # handle overflow like 999 + 1 = 1000
        if length % 2 == 0:
            pal_candidate = left + left[:-1][::-1]
        else:
            pal_candidate = left + left[-2::-1]
    else:
        if length % 2 == 0:
