    """
    Calculate the harmonic sum of n-1.

    Args:
    n (int): The number up to which the harmonic sum is calculated.

    Returns:
    int: The harmonic sum of n-1.
    """
    if n == 0:
        return 0
    else:
        return 1 / n + harmonic_sum(n - 1)

